namespace {struct Token{uint64_t id;};struct BorrowInventory{std::mutex mutex;std::vector<std::unique_ptr<Token>>tokens;std::unordered_map<void*,std::shared_ptr<ProofLoan>>owners;};BorrowInventory&inventory(){static auto*p=new BorrowInventory;return*p;}void*adopt(const std::shared_ptr<ProofLoan>&p){auto&i=inventory();std::lock_guard<std::mutex>lock(i.mutex);if(i.tokens.size()>=65536)return nullptr;auto token=std::make_unique<Token>();token->id=i.tokens.size()+1;void*raw=token.get();i.tokens.push_back(std::move(token));i.owners.emplace(raw,p);return raw;}std::shared_ptr<ProofLoan>lookup(void*raw){auto&i=inventory();std::lock_guard<std::mutex>lock(i.mutex);auto at=i.owners.find(raw);return at==i.owners.end()?nullptr:at->second;}void tombstone(void*raw){auto&i=inventory();std::lock_guard<std::mutex>lock(i.mutex);auto at=i.owners.find(raw);if(at!=i.owners.end())at->second.reset();}}
namespace {using S=ynx_auth_shop_status_v1;bool good(S s){return!s.error_present&&!s.first_code&&!s.unknown;}S bad(int c,bool u=false){return{1,c,uint32_t(u),0};}S checked(S s,bool cleanup=false){return s.error_present>1||s.unknown>1||s.physical_done>1||(!cleanup&&s.physical_done)||(!s.error_present&&s.first_code)?bad(74103,true):s;}int64_t wall(){return std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();}int64_t mono(){return std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now().time_since_epoch()).count();}}
ynx_auth_shop_status_v1 ProofLoan::remember(S s)noexcept{std::lock_guard<std::mutex>lock(mutex_);if(good(first_)&&!good(s))first_=s;return first_;}
bool ProofLoan::window()const noexcept{const auto w=wall(),m=mono();return ready_&&w>=wall_&&w>=issued_&&w<expires_&&m>=mono_&&m-mono_<expires_-wall_;}
std::shared_ptr<ProofLoan>ProofLoan::capture(void*env,ynx_wallet_shop_session_v1*session,ynx_auth_shop_original_client_v1*source,const std::string&id,S&status)noexcept{
 std::shared_ptr<ProofLoan>p;try{p=std::make_shared<ProofLoan>();p->session_=session;p->source_=source;p->token_=adopt(p);if(!p->token_){status=bad(74104);p->remember(status);return p;}auto acquired=ynx_wallet_shop_invoice_introspection_proof_acquire_v1(env,session,source,{reinterpret_cast<const uint8_t*>(id.data()),id.size()});p->raw_=acquired.owner;status=checked(acquired.status); // adopt partial BEFORE raw first0
 if(good(status)&&!p->raw_)status=bad(74103,true);if(!good(status)){p->remember(status);return p;}
 status=checked(ynx_wallet_shop_invoice_introspection_proof_current_actor_v1(env,p->raw_,session,source));if(!good(status)){p->remember(status);return p;}
 std::vector<uint8_t>storage(YNX_ORIGINAL_PRODUCT_SESSION_PROOF_V2_HEADER_MAX);ynx_wallet_shop_invoice_introspection_proof_data_v1 v{};status=checked(ynx_wallet_shop_invoice_introspection_proof_copy_v1(env,p->raw_,session,source,storage.data(),storage.size(),&v));
 const auto a=reinterpret_cast<uintptr_t>(v.original.header_value),b=reinterpret_cast<uintptr_t>(storage.data());bool shape=v.version==1&&v.size==sizeof(v)&&v.original.header_value_bytes>=2&&v.original.header_value_bytes<=storage.size()&&a>=b&&a<=UINTPTR_MAX-v.original.header_value_bytes&&a+v.original.header_value_bytes<=b+storage.size();
 if(shape){p->header_.assign(v.original.header_value,v.original.header_value+v.original.header_value_bytes);p->issued_=v.issued_at_ms;p->expires_=v.expires_at_ms;} // retain bounded late DATA first
 if(!good(status)){p->remember(status);return p;}if(!shape){status=bad(74103);p->remember(status);return p;}
 for(auto c:p->header_)if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='_'||c=='-')){status=bad(74103);p->remember(status);return p;}
 p->wall_=wall();p->mono_=mono();if(p->issued_<0||p->expires_<=p->issued_||p->expires_-p->issued_>60000){status=bad(74103);p->remember(status);return p;}p->ready_=true;status=p->actor(env);return p;
 }catch(...){status=bad(74104,true);if(p)p->remember(status);return p;}
}
ynx_auth_shop_status_v1 ProofLoan::local()noexcept{auto first=remember({});if(!good(first))return first;if(retired_.load(std::memory_order_acquire)||!raw_||!window())return remember(bad(74101));auto s=checked(ynx_wallet_shop_invoice_introspection_proof_current_local_v1(raw_,session_,source_));if(!good(s))return remember(s);if(retired_.load()||!window())return remember(bad(74101));return{};}
ynx_auth_shop_status_v1 ProofLoan::actor(void*env)noexcept{auto s=local();if(!good(s))return s;s=checked(ynx_wallet_shop_invoice_introspection_proof_current_actor_v1(env,raw_,session_,source_));if(!good(s))return remember(s);return local();}
ynx_auth_shop_status_v1 ProofLoan::retire()noexcept{retired_.store(true,std::memory_order_release);if(!retire_selected_){retire_selected_=true;if(raw_)remember(checked(ynx_wallet_shop_invoice_introspection_proof_retire_v1(raw_)));}return remember({});}
ynx_auth_shop_status_v1 ProofLoan::close()noexcept{
 {std::lock_guard<std::mutex>lock(mutex_);if(borrowed_)return bad(74102);}retire();auto result=[&](bool done){auto r=remember({});r.physical_done=done;return r;};if(released_)return result(true);if(!raw_){released_=true;tombstone(token_);return result(true);}if(join_unknown_)return result(false);
 if(!close_selected_){auto joined=checked(ynx_wallet_shop_invoice_introspection_proof_join_v1(raw_),true);if(!joined.physical_done){if(joined.unknown){remember(joined);join_unknown_=true;}auto first=remember({});if(!good(first))return first;return joined;}remember(joined);close_selected_=true;close_result_=checked(ynx_wallet_shop_invoice_introspection_proof_close_v1(raw_),true);close_done_=close_result_.physical_done;remember(close_result_);if(!close_done_){close_result_.unknown=1;if(good(remember({})))remember(bad(74104,true));}}
 if(!close_done_){auto r=result(false);r.unknown=1;return r;}
 if(!release_selected_){release_selected_=true;release_result_=checked(ynx_wallet_shop_invoice_introspection_proof_release_closed_v1(raw_),true);remember(release_result_);if(release_result_.physical_done){released_=true;raw_=nullptr;header_.clear();tombstone(token_);}else if(good(remember({})))remember(bad(74104,true));}
 auto r=result(released_);if(!released_)r.unknown=1;return r;
}
ynx_auth_shop_proof_borrow_v1*ProofLoan::beginBorrow(ynx_auth_shop_original_client_v1*s,S&status)noexcept{status=local();if(!good(status))return nullptr;std::lock_guard<std::mutex>lock(mutex_);if(s!=source_||borrowed_||retired_.load()){status=bad(74101);return nullptr;}borrower_=std::this_thread::get_id();borrowed_=1;return reinterpret_cast<ynx_auth_shop_proof_borrow_v1*>(token_);}
void ProofLoan::endBorrow()noexcept{std::lock_guard<std::mutex>lock(mutex_);if(borrowed_&&borrower_==std::this_thread::get_id()){borrowed_=0;borrower_={};}}
S ProofLoan::borrowedCurrent(ynx_auth_shop_original_client_v1*s)noexcept{{std::lock_guard<std::mutex>lock(mutex_);if(s!=source_||!borrowed_||borrower_!=std::this_thread::get_id())return bad(74101);}return local();}
