extern "C" S ynx_auth_shop_proof_borrow_current_v1(ynx_auth_shop_proof_borrow_v1*p,ynx_auth_shop_original_client_v1*s){auto owner=lookup(p);return owner?owner->borrowedCurrent(s):bad(74101);}
extern "C" S ynx_auth_shop_proof_borrow_copy_v1(ynx_auth_shop_proof_borrow_v1*p,ynx_auth_shop_original_client_v1*s,uint8_t*b,size_t n,ynx_wallet_shop_invoice_introspection_proof_data_v1*out){auto owner=lookup(p);return owner?owner->borrowedCopy(s,b,n,out):bad(74101);}
